import type { Metadata } from 'next';
import { productCatalog } from '@/data/productCatalog';
import { siteConfig } from '@/data/siteConfig';

/** Brand share card generated by `src/app/opengraph-image.tsx`. */
export const defaultOgImage = '/opengraph-image';

/** Absolute URL for a site path — used in sitemap, canonical and JSON-LD. */
export function absoluteUrl(path = '/'): string {
  return new URL(path, siteConfig.siteUrl).toString();
}

interface PageMetadataInput {
  title: string;
  description: string;
  path: string;
  /** share-card image path; defaults to the brand card */
  image?: string;
}

/** Page metadata with canonical + Open Graph + Twitter filled in consistently. */
export function buildPageMetadata({ title, description, path, image = defaultOgImage }: PageMetadataInput): Metadata {
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: {
      title,
      description,
      url: path,
      type: 'website',
      siteName: siteConfig.name,
      locale: 'en_IN',
      images: [{ url: image, width: 1200, height: 630, alt: title }],
    },
    twitter: { card: 'summary_large_image', title, description, images: [image] },
  };
}

export function buildBreadcrumbSchema(items: Array<{ name: string; path: string }>) {
  return {
    '@context': 'https://schema.org',
    '@type': 'BreadcrumbList',
    itemListElement: items.map((item, index) => ({
      '@type': 'ListItem',
      position: index + 1,
      name: item.name,
      item: absoluteUrl(item.path),
    })),
  };
}

export function buildFaqSchema(faqs: Array<{ question: string; answer: string }>) {
  return {
    '@context': 'https://schema.org',
    '@type': 'FAQPage',
    mainEntity: faqs.map((faq) => ({
      '@type': 'Question',
      name: faq.question,
      acceptedAnswer: { '@type': 'Answer', text: faq.answer },
    })),
  };
}

/** The business itself — one canonical entity, referenced from every page via @id. */
export function buildLocalBusinessSchema() {
  const [streetLineOne, streetLineTwo] = siteConfig.addressLines;
  return {
    '@context': 'https://schema.org',
    '@type': ['LocalBusiness', 'ProfessionalService'],
    '@id': absoluteUrl('/#business'),
    name: siteConfig.name,
    alternateName: [...siteConfig.alternateNames],
    slogan: siteConfig.slogan,
    url: siteConfig.siteUrl,
    description:
      'Offset printing and packaging press in Ahmedabad — visiting cards, brochures, boxes, stickers, pouches and more, designed and printed under one roof since 2008.',
    foundingDate: String(siteConfig.foundedYear),
    telephone: `+${siteConfig.whatsappNumber}`,
    email: siteConfig.email,
    image: absoluteUrl('/favicon.png'),
    logo: absoluteUrl('/favicon.png'),
    priceRange: '₹₹',
    hasMap: siteConfig.googleProfileUrl,
    address: {
      '@type': 'PostalAddress',
      streetAddress: `${streetLineOne} ${streetLineTwo}`,
      addressLocality: 'Ahmedabad',
      addressRegion: 'Gujarat',
      postalCode: '382330',
      addressCountry: 'IN',
    },
    geo: {
      '@type': 'GeoCoordinates',
      latitude: siteConfig.geo.latitude,
      longitude: siteConfig.geo.longitude,
    },
    openingHoursSpecification: [
      {
        '@type': 'OpeningHoursSpecification',
        dayOfWeek: ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'],
        opens: '10:00',
        closes: '19:00',
      },
    ],
    areaServed: { '@type': 'State', name: 'Gujarat' },
    sameAs: [siteConfig.googleProfileUrl, siteConfig.facebookUrl, siteConfig.instagramUrl],
    knowsAbout: productCatalog.map((product) => `${product.name} printing`),
  };
}

interface WebPageSchemaInput {
  name: string;
  description: string;
  path: string;
  /** schema.org type — `WebPage` by default */
  pageType?: 'WebPage' | 'AboutPage' | 'ContactPage' | 'CollectionPage';
}

/**
 * Page entity for answer engines: ties the page to the business and website, states when the
 * content was last reviewed, and marks the answer-first copy (`[data-speakable]`) for voice assistants.
 */
export function buildWebPageSchema({ name, description, path, pageType = 'WebPage' }: WebPageSchemaInput) {
  return {
    '@context': 'https://schema.org',
    '@type': pageType,
    '@id': `${absoluteUrl(path)}#webpage`,
    url: absoluteUrl(path),
    name,
    description,
    inLanguage: 'en-IN',
    dateModified: siteConfig.contentLastUpdated,
    isPartOf: { '@id': absoluteUrl('/#website') },
    about: { '@id': absoluteUrl('/#business') },
    speakable: { '@type': 'SpeakableSpecification', cssSelector: ['[data-speakable]'] },
  };
}

export function buildHowToSchema(
  name: string,
  steps: Array<{ title: string; body: string }>,
) {
  return {
    '@context': 'https://schema.org',
    '@type': 'HowTo',
    name,
    step: steps.map((step, index) => ({
      '@type': 'HowToStep',
      position: index + 1,
      name: step.title,
      text: step.body,
    })),
  };
}

/** Ordered list of pages — gives answer engines the full product / area inventory in one object. */
export function buildItemListSchema(name: string, items: Array<{ name: string; path: string }>) {
  return {
    '@context': 'https://schema.org',
    '@type': 'ItemList',
    name,
    numberOfItems: items.length,
    itemListElement: items.map((item, index) => ({
      '@type': 'ListItem',
      position: index + 1,
      name: item.name,
      url: absoluteUrl(item.path),
    })),
  };
}

export function buildWebSiteSchema() {
  return {
    '@context': 'https://schema.org',
    '@type': 'WebSite',
    '@id': absoluteUrl('/#website'),
    name: siteConfig.name,
    url: siteConfig.siteUrl,
    publisher: { '@id': absoluteUrl('/#business') },
    inLanguage: 'en-IN',
  };
}
